#!/usr/bin/env bash
#SBATCH -c 8
#SBATCH --mem 32G
#SBATCH --gres gpu:1
#SBATCH -t 1-00:00
#SBATCH -J wsi-trident-adapter
#SBATCH -o out/stdout.txt
#SBATCH -e out/stderr.txt
#SBATCH --export=NONE

# ==============================================================
#   WSI-TRIDENT-ADAPTER JOB TEMPLATE (profile: compute-canada)
#   Generated by: wsi-trident-adapter script (__VERSION__)
#
#   • You may modify SLURM directives above (partition, mem, time, etc.)
#   • Edit all placeholders below (<...>) before submission.
#   • Submit the job with:  sbatch this_file.sh
# ==============================================================

set -euo pipefail
umask 002

# ==============================================================
#   USER-DEFINED INPUTS  —  EDIT THESE BEFORE SUBMITTING
# ==============================================================

# (1) Python environment setup
#     Option A: virtualenv
#         source ".venv/bin/activate"
#     Option B: conda
#         conda activate your-env
#
#     Keep one method and remove the other completely.
#     The template will fail if no valid environment is active.
source .venv/bin/activate

# (2) Task to run: one of [all, seg, patch, feat]
TASK="<TASK>"

# (3) Path to configuration YAML
#     Example: CONFIG_PATH="config.yaml"
#     To print a default template:
#         wsi-trident-adapter config
CONFIG_PATH="<CONFIG_PATH>"

# ==============================================================
#   END OF USER INPUTS
# ==============================================================

# ---- Sanity check: ensure wsi-trident-adapter is available ----
if ! command -v wsi-trident-adapter &> /dev/null; then
    echo "[ERROR] Python environment not loaded or adapter not installed." >&2
    echo "        Please activate your environment before submission." >&2
    exit 1
fi

# ---- Load profile modules ----
while read -r mod; do
    [[ -n "$mod" ]] && module load "$mod"
done < <(wsi-trident-adapter profile modules)

# ---- Guard for unedited placeholders ----
if [[ "$TASK" == "<TASK>" || "$CONFIG_PATH" == "<CONFIG_PATH>" ]]; then
    echo "[ERROR] Please edit TASK and CONFIG_PATH before sbatch." >&2
    exit 1
fi

# ---- Asset paths ----
WSI_ASSETS_ROOT="$(wsi-trident-adapter profile root)"
export TRIDENT_HOME="${WSI_ASSETS_ROOT}/weights/trident"
export TORCH_HOME="${WSI_ASSETS_ROOT}/weights/torch"
export HF_HOME="${WSI_ASSETS_ROOT}/weights/huggingface"

# ---- Run adapter ----
echo "[INFO] Starting wsi-trident-adapter (profile: compute-canada)"
wsi-trident-adapter run --task "$TASK" --config "$CONFIG_PATH"

echo "[INFO] Job completed successfully."